NEW_FILES = {'test_ramp_cut.py': '"""A ramp\'s slab cut stops at its head, is railed, and leaves the floor past the head clear (0.241.0).\n\nFound by the factory\'s install test 10: a stranger\'s first `make` picked seed 9205, whose lot stands a\nparking_garage, and Level Factory\'s drop-edge gate refused the export on 33 edges round the garage\'s ramp -- the cut\n`stairwell.ramp_hole` made ran from the ramp\'s middle to half a run PAST its head, so the storey it climbs to stood\nopen over nothing for 5 m beyond the top of the ramp, a 3 m fall at most of its edges, and the cut\'s other edges\ndropped onto the ramp unguarded. Every library ramp did the same, 5 to 8 m past its head (the factory\'s\ndocs/findings/ramp_cut_241/). On 0.240.0 every test here fails: the cut runs past the head, nothing rails it,\n`ramp_landing` does not exist, and a guard\'s material was the builder\'s alone to choose.\n"""\nimport os\n\nimport spec_loader\nimport stairwell\nfrom spec_types import Ramp\n\nHERE = os.path.dirname(os.path.abspath(__file__))\nT = stairwell.GUARD_THICK\n#: Every library spec with a ramp that cuts a slab, as the census read them (9 ramps).\nRAMP_SPECS = ("cbp_town_finale_midbalanced_schemafixed", "cr_garage", "foundry_heist_vertical", "parking_garage",\n              "parking_garage_a01", "parking_garage_a02")\n\n\ndef _cut_ramps():\n    for stem in RAMP_SPECS:\n        spec = spec_loader.load_spec(os.path.join(HERE, "specs", stem + ".json"))\n        for i, rp in enumerate(spec.ramps):\n            if rp.cut_slabs and rp.to_story > rp.from_story:\n                yield stem, spec, i, rp\n\n\ndef _span(rect, axis):\n    cx, cy, sx, sy = rect\n    return (cy - sy / 2, cy + sy / 2) if axis == "Y" else (cx - sx / 2, cx + sx / 2)\n\n\ndef test_the_library_has_the_ramps_this_file_reads():\n    """A test over a list that went empty would prove nothing."""\n    assert sum(1 for _ in _cut_ramps()) == 9\n\n\ndef test_a_ramps_cut_stops_at_its_head():\n    """The ramp\'s box is centred on (x, y) and climbs toward +axis, so its head is half a run ahead of the centre;\n    the cut ends there and never past it, and begins at the ramp\'s middle, where it always has. A synthetic ramp along\n    X holds the other axis to the same rule (no library ramp runs along X)."""\n    ramps = [(stem, i, rp) for stem, _s, i, rp in _cut_ramps()]\n    ramps.append(("synthetic X", 0, Ramp(x=2.0, y=-3.0, from_story=0, to_story=1, run=10.0, width=3.0, axis="X")))\n    for stem, i, rp in ramps:\n        centre = rp.y if rp.axis == "Y" else rp.x\n        lo, hi = _span(stairwell.ramp_hole(rp), rp.axis)\n        assert abs(hi - (centre + rp.run / 2)) < 1e-9, (stem, i, "the cut ends at", hi, "the head is",\n                                                         centre + rp.run / 2)\n        assert abs(lo - centre) < 1e-9, (stem, i, lo)\n        cx, cy, sx, sy = stairwell.ramp_hole(rp)\n        assert abs((sx if rp.axis == "Y" else sy) - (rp.width + 2 * stairwell.RAMP_CUT_SIDE)) < 1e-9, (stem, i)\n\n\ndef test_a_ramps_cut_is_railed_and_its_head_left_open():\n    """`stair_guards` rails the cut as it rails a flight\'s hole: both long edges and the entry end, `GUARD_THICK / 2`\n    outside it, on the storey whose slab it opens -- and nothing across the head, the way off the ramp. Where a rail is\n    trimmed, it is by what the stair rule trims for (furniture on its line, a wall holding it), so the kept pieces\n    stay on the right lines."""\n    for stem, spec, i, rp in _cut_ramps():\n        lo, hi = _span(stairwell.ramp_hole(rp), rp.axis)\n        cx, cy, sx, sy = stairwell.ramp_hole(rp)\n        lat0, lat1 = (cx - sx / 2, cx + sx / 2) if rp.axis == "Y" else (cy - sy / 2, cy + sy / 2)\n        mine = [g for g in stairwell.stair_guards(spec) if g["stair"] == "ramp_%d" % i]\n        assert mine, (stem, i, "no rail round the cut")\n        assert all(g["kind"] == "rail" and g["story"] == rp.to_story for g in mine), (stem, i)\n        lateral = "X" if rp.axis == "Y" else "Y"\n        sides = {round(g["pos"], 6) for g in mine if g["axis"] == rp.axis}\n        assert sides <= {round(lat0 - T / 2, 6), round(lat1 + T / 2, 6)} and sides, (stem, i, sides)\n        ends = {round(g["pos"], 6) for g in mine if g["axis"] == lateral}\n        assert ends == {round(lo - T / 2, 6)}, (stem, i, "the entry end", ends, "not the head", hi)\n        for g in mine:\n            if g["axis"] == rp.axis:\n                assert lo - 1e-9 <= g["lo"] and g["hi"] <= hi + 1e-9, (stem, i, g)\n\n\ndef test_the_garages_rails_are_whole():\n    """Where nothing stands on a rail\'s line it runs the whole edge: each garage ramp\'s three rails, untrimmed."""\n    for stem, spec, i, rp in _cut_ramps():\n        if "garage" not in stem:\n            continue\n        lo, hi = _span(stairwell.ramp_hole(rp), rp.axis)\n        mine = [g for g in stairwell.stair_guards(spec) if g["stair"] == "ramp_%d" % i]\n        assert len(mine) == 3, (stem, i, mine)\n        for g in mine:\n            if g["axis"] == rp.axis:\n                assert (abs(g["lo"] - lo) < 1e-9 and abs(g["hi"] - hi) < 1e-9), (stem, i, g)\n\n\ndef test_no_wall_stands_across_a_ramps_head():\n    """`ramp_landing` is a wall void past the head, as deep as the ramp is wide or IBC\'s 60 in, whichever is more,\n    reaching back over the cut\'s last `RAMP_CUT_SIDE`: floor a body or a car arrives on, not a hole. Two library walls stood across a ramp\'s arrival and were clipped\n    only by the old cut running past the head: foundry_heist_vertical\'s `int_0_4` on the head itself, and\n    parking_garage_a02\'s wall at y 6, 1 m past ramp 0\'s head. Both still open where the ramp arrives."""\n    import partition_bounds as PB\n    import setbacks\n    for stem, spec, i, rp in _cut_ramps():\n        land = stairwell.ramp_landing(rp)\n        assert land in stairwell.wall_voids(spec)[rp.to_story], (stem, i)\n        depth = (land[3] - land[1]) if rp.axis == "Y" else (land[2] - land[0])\n        assert abs(depth - max(rp.width, stairwell.RAMP_LANDING_MIN) - stairwell.RAMP_CUT_SIDE) < 1e-9, (stem, i, depth)\n        assert stairwell.ramp_landing(rp) not in stairwell.slab_openings(spec).get(rp.to_story, ()), (stem, i)\n    for stem, story, axis, pos in (("foundry_heist_vertical", 0, "X", -4.0), ("parking_garage_a02", 1, "X", 6.0)):\n        spec = spec_loader.load_spec(os.path.join(HERE, "specs", stem + ".json"))\n        p = next(p for p in spec.partitions if (p.story, p.axis, p.pos) == (story, axis, pos))\n        spans = PB.partition_spans(p.start, p.end, p.axis, p.pos, spec.footprint_x, spec.footprint_y,\n                                   stairwell.wall_voids(spec).get(p.story, ()), min_span=spec.wall_thick,\n                                   extent=setbacks.storey_extent(spec, p.story))\n        assert len(spans) == 2, (stem, spans)\n\n\ndef test_a_ramps_rails_are_steel_where_the_palette_has_it():\n    """A garage\'s guardrail is painted steel, not a stair\'s wood: the rails carry `material`, and the builder takes a\n    piece\'s own material before its wood-where-the-palette-has-it default."""\n    for stem, spec, i, rp in _cut_ramps():\n        mats = {m.id for m in spec.materials}\n        want = "metal_painted" if "metal_painted" in mats else ("metal" if "metal" in mats else None)\n        for g in stairwell.stair_guards(spec):\n            if g["stair"] == "ramp_%d" % i:\n                assert g.get("material") == want, (stem, i, g.get("material"))\n    src = open(os.path.join(HERE, "deli_counter.py"), encoding="utf-8").read()\n    assert \'mat = g.get("material") or ("wood" if "wood" in have else None)\' in src\n'}
CHANGELOG = '## [0.241.0] - a ramp\'s cut stops at its head, railed, with a landing past it\n\n**Found by the factory\'s install test 10** (roadmap 202): a stranger\'s first `make` picked seed 9205, whose lot\nstands a parking_garage, and Level Factory\'s drop-edge gate refused the export on 33 edges round the garage\'s ramp.\n`stairwell.ramp_hole` cut the storey a ramp climbs to from the ramp\'s middle to half a run PAST its head -- the box\n`Builder._ramps` builds is centred on the ramp\'s (x, y) -- so the cut\'s far half stood open over nothing, 5 m beyond\nthe top of the garage\'s ramp (24 of the edges, most of them a 3 m fall to the ground floor), and the cut\'s other edges\ndropped 0.75 to 1.2 m onto the ramp unguarded (9). Every library ramp did the same: nine ramps in six specs, 5 to 8 m\npast their heads (the factory\'s `docs/findings/ramp_cut_241/`).\n\n### Changed\n- `stairwell.ramp_hole`: the cut runs from the ramp\'s middle -- where it always began -- to its head, and never past\n  it; across the ramp\'s width and `RAMP_CUT_SIDE` (0.2 m) either side, as before. `ramp_cut_span` says where. Along X\n  the same rule: the old cut covered an X ramp\'s whole footprint (no library ramp runs along X).\n- `stairwell.stair_guards` rails a ramp\'s cut as it rails a flight\'s hole: `GUARD_HEIGHT` rails along both long edges\n  and across the entry end, `GUARD_THICK / 2` outside the cut, on the storey whose slab it opens; the head stays open,\n  the way off. They come after every stair\'s pieces, so every existing guard keeps its index and its name\n  (`stair_guard_rail_<k>`), and they take every trim a stair\'s rail takes -- furniture on the line, a wall holding it.\n  Painted steel where the palette has it (`metal_painted`, else `metal`), a garage\'s guardrail rather than a stair\'s\n  wood: the builder takes a piece\'s own `material` before its wood-where-the-palette-has-it default.\n- `stairwell.ramp_landing`: a wall void past a ramp\'s head, as deep as the ramp is wide or the 60 in that IBC 2018\n  section 1012.6.3 asks of a ramp landing, whichever is more, and reaching back over the cut\'s last `RAMP_CUT_SIDE` --\n  floor, not a hole -- so no partition stands across a ramp\'s arrival. Two library walls did, clipped only by the old\n  cut running past the head: foundry_heist_vertical\'s `int_0_4`, its centreline on the head, and parking_garage_a02\'s\n  wall at y 6, 1 m past ramp 0\'s. A landing begun at the head left `int_0_4` standing --\n  `partition_bounds.hole_cuts` decides by a wall\'s centreline, strictly inside -- found by the new tests before it\n  shipped.\n\n### Not changed, and why\n- WHERE THE CUT BEGINS. Where each cut begins, the clearance between the slab\'s underside and the ramp\'s top face is\n  1.04 to 1.55 m on the nine library ramps, under a body\'s 1.8 m, so a body walking up meets the slab\'s edge. The agent\n  contract\'s `min_headroom_m` would open each cut 1.4 to 3.2 m further down its ramp, under furniture that furnish\n  lays without reading a ramp\'s cut (foundry_heist_vertical\'s forklift and pallets, cbp_town\'s chairs), so it waits on\n  furnish learning ramps -- the factory\'s roadmap, open.\n- A RAMP\'S OWN SIDES. The drop from a ramp to the floor beside it is reported by Level Factory\'s gate as a thing\'s\n  top, not refused; walls or rails along them would change the garages\' ground floors, and are the walker\'s call.\n\n### Tests\n- `test_ramp_cut.py`, 6 new; 5 fail on 0.240.0 -- the cut ending 5 to 8 m past the head, nothing railing it, the\n  garages\' three rails missing, no `ramp_landing`, the builder ignoring a piece\'s material -- and the sixth, the\n  library\'s nine cut ramps, is the floor under them.\n- `test_wall_over_void.py`: the ramp\'s cut no longer described as "offset half a run".\n\n'
OLD_VERSION, NEW_VERSION = 'Deli Counter 0.240.0', 'Deli Counter 0.241.0'


def _sha(b):
    return hashlib.sha256(b).hexdigest()[:16]


def _read(name):
    """The file's LF text and whether it is CRLF on disk; refuses mixed endings and a file that is not the pinned one."""
    raw = (REPO / name).read_bytes()
    crlf, lf = raw.count(b"\r\n"), raw.count(b"\n")
    if crlf not in (0, lf):
        raise SystemExit("REFUSED: deli_counter/%s has mixed line endings (%d CRLF of %d); nothing written"
                         % (name, crlf, lf))
    text = raw.decode("utf-8").replace("\r\n", "\n")
    if _sha(text.encode("utf-8")) != PINS[name]:
        raise SystemExit("REFUSED: deli_counter/%s is %s, not the %s this patch was written against; nothing "
                         "written" % (name, _sha(text.encode("utf-8")), PINS[name]))
    return text, crlf > 0


def main(argv):
    # every file worked out and checked before any is written
    out = {}
    for name, edits in EDITS.items():
        text, crlf = _read(name)
        for what, old, new in edits:
            if text.count(old) != 1:
                raise SystemExit("REFUSED: deli_counter/%s: the anchor at %s is there %d times; nothing written"
                                 % (name, what, text.count(old)))
            text = text.replace(old, new)
        out[name] = text.replace("\n", "\r\n") if crlf else text
    for name in NEW_FILES:
        if (REPO / name).exists():
            raise SystemExit("REFUSED: deli_counter/%s exists already; nothing written" % name)
    v = REPO / "VERSION"
    if v.read_bytes().decode("utf-8") != OLD_VERSION:
        raise SystemExit("REFUSED: VERSION reads %r, not %s; nothing written" % (v.read_text(), OLD_VERSION))
    cl = REPO / "CHANGELOG.md"
    craw = cl.read_bytes()
    if b"\r\n" in craw or not craw.startswith(b"## [" + OLD_VERSION.split()[-1].encode() + b"]"):
        raise SystemExit("REFUSED: CHANGELOG.md is not LF opening on %s; nothing written" % OLD_VERSION)
    for name, text in out.items():
        (REPO / name).write_bytes(text.encode("utf-8"))
    for name, text in NEW_FILES.items():
        (REPO / name).write_bytes(text.encode("utf-8"))
    v.write_bytes(NEW_VERSION.encode("utf-8"))
    cl.write_bytes(CHANGELOG.encode("utf-8") + craw)
    print("%s applied: %d files edited, %d written, VERSION, CHANGELOG. Now, in deli_counter/: build.py --all, "
          "suite" % (NEW_VERSION, len(out), len(NEW_FILES)))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
